	(393, 14, 39, NULL, 'JS-to-TS Conversion Lab', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "JS-to-TS Conversion Lab", "Sub-Topic": "Convert the JS loan-eligibility/validation modules into type-safe TS", "Phase / Module": "TypeScript", "Learning Format": "Embedded Assignments (code editor)", "Learning Outcome": "Learner can retrofit type safety onto existing JavaScript code", "Artefact(s) Produced": "TS files (compiler-validated, zero type errors)", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.75", "Assignment(s) — realistic time incl. buffer": "A1 (10 min): Define an ''Applicant'' interface with correctly typed fields (string/number).\nA2 (10 min): Define an ''EligibilityResult'' interface with a status: ''approved'' | ''referred'' | ''rejected'' union type.\nA3 (15 min): Convert the PAN/mobile validation functions (from the JS lab) into typed TS functions, fixing compiler errors.\nA4 (15 min): Convert the EMI-calculation function into a type-safe TS function and verify zero type errors on build."}'),
	(394, 14, 40, NULL, 'Knowledge Check', '{"Phase": "Phase 3 — Web & Scripting", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded coding assessment", "Phase / Module": "TypeScript", "Learning Format": "Auto-graded Coding Assessment", "Learning Outcome": "Validated TypeScript competency", "Milestone / Gate": "MILESTONE 3 — Web & Scripting Gate: all 3 Phase 3 checks passed -> unlocks Phase 4", "Artefact(s) Produced": "Coding assessment report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "Assessment scope: independent TS conversion/typing task scored on compiler validation"}'),
	(395, 14, 42, NULL, 'WebDriver Architecture & Locators + Step-1 Automation', '{"Phase": "Phase 4 — Test Automation", "Topic": "WebDriver Architecture & Locators + Step-1 Automation", "Sub-Topic": "WebDriver architecture, locator strategies, implicit vs explicit vs fluent waits, Actions class for complex interactions", "Phase / Module": "Selenium", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can select reliable locator/wait strategies and automate a single UI step", "Artefact(s) Produced": "Automation script (Step 1, auto-captured)", "Video / Content (hrs)": "1.5", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Identify and write robust locators (ID/CSS/XPath) for the 5 key fields on the Applicant Details page.\nA2 (15 min): Implement explicit-wait handling for the asynchronous CIBIL-score-check loading spinner.\nA3 (20 min): Automate filling and submitting the Applicant Details step (Step 1) end-to-end.\nA4 (10 min): Add an assertion verifying navigation to Step 2 (Income Details) after successful submission."}'),
	(396, 14, 43, NULL, 'Page Object Model + POM Build-Out', '{"Phase": "Phase 4 — Test Automation", "Topic": "Page Object Model + POM Build-Out", "Sub-Topic": "POM design pattern for maintainable automation suites, base page class pattern, separating locators from test logic", "Phase / Module": "Selenium", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can structure automation code using the POM pattern across a multi-step flow", "Artefact(s) Produced": "POM class files (auto-validated)", "Video / Content (hrs)": "1.5", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Build an ''ApplicantDetailsPage'' POM class encapsulating Step 1 locators and actions.\nA2 (15 min): Build an ''IncomeDetailsPage'' POM class encapsulating Step 2 locators and actions.\nA3 (20 min): Build a ''DocumentUploadPage'' POM class encapsulating Step 3 locators and the file-upload action.\nA4 (15 min): Wire the 3 POM classes together in a single test orchestrating Steps 1 -> 3 sequentially."}'),
	(397, 14, 44, NULL, 'Automation Lab — Full Flow Execution', '{"Phase": "Phase 4 — Test Automation", "Topic": "Automation Lab — Full Flow Execution", "Sub-Topic": "End-to-end execution and negative-path testing against the sandbox app", "Phase / Module": "Selenium", "Learning Format": "Embedded Assignments (automation sandbox + browser)", "Learning Outcome": "Learner can independently automate and validate a multi-step web user flow end-to-end", "Artefact(s) Produced": "Automation script + execution report (auto-captured)", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Execute the full 3-step automation against the sandbox app and capture a pass/fail execution report.\nA2 (15 min): Introduce a deliberate locator break and verify the suite fails gracefully with a clear error message (negative test)."}'),
	(398, 14, 45, NULL, 'Knowledge Check', '{"Phase": "Phase 4 — Test Automation", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded script execution assessment", "Phase / Module": "Selenium", "Learning Format": "Auto-graded Coding Assessment", "Learning Outcome": "Validated Selenium automation competency", "Milestone / Gate": "Gate 4a — pass to proceed", "Artefact(s) Produced": "Script execution report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "Assessment scope: independent automation task scored on script execution success against sandbox app"}'),
	(399, 14, 47, NULL, 'BDD Concepts & Gherkin Syntax + Scenario Drafting', '{"Phase": "Phase 4 — Test Automation", "Topic": "BDD Concepts & Gherkin Syntax + Scenario Drafting", "Sub-Topic": "BDD principles, Gherkin (Given/When/Then), feature file structure, Scenario Outline & Examples tables, tagging, step definitions", "Phase / Module": "Cucumber", "Learning Format": "Self-paced Video + Embedded Assignment", "Learning Outcome": "Learner can write business-readable Gherkin scenarios", "Video / Content (hrs)": "1", "Assignment / Hands-on (hrs)": "0.25", "Assignment(s) — realistic time incl. buffer": "A1 (15 min): Write a Gherkin scenario (Given/When/Then) for the ''auto-approved applicant'' happy path."}'),
	(400, 14, 48, NULL, 'Cucumber–Selenium Integration + Feature & Step-Def Lab', '{"Phase": "Phase 4 — Test Automation", "Topic": "Cucumber–Selenium Integration + Feature & Step-Def Lab", "Sub-Topic": "Tying Cucumber step definitions to Selenium automation", "Phase / Module": "Cucumber", "Learning Format": "Self-paced Video + Embedded Assignments", "Learning Outcome": "Learner can build and execute a working, multi-scenario BDD automation suite", "Artefact(s) Produced": "Feature files + step definitions + execution report", "Video / Content (hrs)": "1", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "A1 (10 min): Write a Gherkin scenario for the ''missing mandatory field'' validation case.\nA2 (10 min): Write a Gherkin scenario for the ''ineligible applicant rejection'' case.\nA3 (20 min): Implement step definitions wiring all 3 scenarios to the existing Selenium POM classes.\nA4 (15 min): Execute all 3 scenarios against the sandbox app and confirm pass/fail status per scenario."}'),
	(401, 14, 49, NULL, 'Knowledge Check', '{"Phase": "Phase 4 — Test Automation", "Topic": "Knowledge Check", "Sub-Topic": "Auto-graded execution-based assessment", "Phase / Module": "Cucumber", "Learning Format": "Auto-graded Execution-based Assessment", "Learning Outcome": "Validated BDD/Cucumber automation competency", "Milestone / Gate": "MILESTONE 4 — Test Automation Gate: all Phase 4 checks passed -> unlocks Capstone", "Artefact(s) Produced": "Execution report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "0.5", "Assignment(s) — realistic time incl. buffer": "Assessment scope: independent BDD scenario authored and executed against sandbox app"}'),
	(402, 14, 51, NULL, 'Digital Lending Platform — Integrated End-to-End Test Suite', '{"Phase": "Capstone", "Topic": "Digital Lending Platform — Integrated End-to-End Test Suite", "Sub-Topic": "Integrated end-to-end test of the Mphasis Digital Lending Platform sandbox application — a multi-step loan origination flow (Applicant Onboarding -> Eligibility Check -> Document Upload -> Approval Decision -> DB-confirmed disbursement status). Context: Mphasis is rolling out a new Digital Lending Platform for a banking client; as a QA engineering pod member, you build the foundational automated test suite ahead of UAT.", "Phase / Module": "Capstone Use Case", "Learning Format": "Embedded Assignments (full sandbox: app + DB + automation tooling)", "Learning Outcome": "Learner demonstrates integrated, independent application of all four core skill clusters (Java/JUnit, SQL, Selenium, Cucumber) on a single realistic BFSI scenario — the capstone readiness signal. Success criteria: all 3 Cucumber scenarios execute end-to-end without manual intervention, and the DB validation query returns the expected state for each.", "Artefact(s) Produced": "Capstone repo: Java classes + JUnit suite, POM-based Selenium scripts, Cucumber feature files + step definitions, SQL validation query, execution/test report", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "2", "Assignment(s) — realistic time incl. buffer": "A1 (30 min): Java + JUnit: extend ''LoanEligibilityChecker'' with a new ''calculateRiskScore()'' method combining CIBIL score, EMI ratio, and existing exposure; write a JUnit suite (min. 3 cases) covering edge cases such as a zero-income applicant and a maxed-out exposure applicant.\nA2 (30 min): Selenium (POM): automate the complete UI journey — applicant onboarding through to the approval decision screen — reusing the Page Object Model classes built in Phase 4.\nA3 (30 min): Cucumber (BDD): author a feature file with 3 end-to-end scenarios (auto-approved, manually-referred, rejected applicant) and wire step definitions to the Selenium automation.\nA4 (15 min): MySQL: write a validation query confirming the ''loan_applications'' table reflects the correct ''approval_status'' and ''disbursement_flag'' after each scenario executes, closing the UI-to-database loop."}'),
	(403, 14, 52, NULL, 'Consolidated Readiness Scoring', '{"Phase": "Capstone", "Topic": "Consolidated Readiness Scoring", "Sub-Topic": "Final baseline assessment & readiness report generation", "Phase / Module": "Final Readiness Baseline", "Learning Format": "Auto-graded Assessment + System Report", "Learning Outcome": "Generates a consolidated per-learner readiness score across all 10 skill nodes, used to gate/route entry into the full Fresher Training Program", "Milestone / Gate": "FINAL GATE — Program Completion: readiness score released to Fresher Training Program intake", "Artefact(s) Produced": "Readiness Baseline Report (PDF/dashboard export) — phase scores, skill-node scores, capstone outcome, overall readiness rating", "Video / Content (hrs)": "0", "Assignment / Hands-on (hrs)": "1", "Assignment(s) — realistic time incl. buffer": "Assessment scope: consolidated scoring across all 10 skill nodes plus capstone outcome — no new problem statement, system-generated"}'),
