	(498, 21, 10, NULL, 'Unstructured/Semi-Structured Data - 1', '{"Coverage": "Understanding of options for storing unstructured/semi-structured data: Azure Storage & Cosmos DB\nWhat is Azure Cosmos DB?\nKey Features (Global Distribution, Low Latency)\nUnderstanding Request Units (RUs)\nData Modelling with JSON Documents\nPartition Key Basics\nCRUD Operations in Cosmos DB", "Daily Topic": "Unstructured/Semi-Structured Data - 1", "Focus of the week": "Week 1: Foundations & Data Essentials"}'),
	(499, 21, 11, NULL, 'Unstructured/Semi-Structured Data - 2', '{"Coverage": "Querying with SQL API\nConsistency Levels\nUsing Azure Portal for Cosmos DB\nBasic Security and Access Control\nIntroduction to OCR\nAzure Doc Intelligence\nReading pdfs through Open source libraries like PyMuPDF,Tesseract,PyPDF", "Daily Topic": "Unstructured/Semi-Structured Data - 2", "Focus of the week": "Week 1: Foundations & Data Essentials"}'),
	(500, 21, 12, NULL, 'Data Pipelines', '{"Coverage": "Introduction to Data Pipelines\nUsing Python for Automation (Scripts, Scheduling)                                                                                                                                                                                                                                      - Introduction to pipeline creation tool: AzureML", "Daily Topic": "Data Pipelines", "Focus of the week": "Week 1: Foundations & Data Essentials"}'),
	(501, 21, 14, NULL, 'Python Configs, Validation & Microservices Basics', '{"Coverage": "Working with JSON, YAML, and Config files in Python\nIntroduction to Pydantic for Data Validation & Serialization\nLogging, Error Handling, and Structuring Python Projects\nREST API Principles & Microservices Overview\nFlask basics (webapp, routes) & Building Lightweight APIs", "Daily Topic": "Python Configs, Validation & Microservices Basics", "Focus of the week": "Week 2: Application Essentials & Generative AI Essentials"}'),
	(502, 21, 15, NULL, 'Building Microservices with FastAPI,Flask & introduction to Azure', '{"Coverage": "FastAPI Essentials: Path, Query, Body, Status Codes\nPydantic Schemas in FastAPI: Validation, Models, Nested Schemas\nUnit testing APIs with pytest\nAzure Fundamentals: Resource Groups, Storage, Managed Identity", "Daily Topic": "Building Microservices with FastAPI,Flask & introduction to Azure", "Focus of the week": "Week 2: Application Essentials & Generative AI Essentials"}'),
	(503, 21, 16, NULL, 'Core Azure Services: Compute, Messaging, Load Balancing & Databricks', '{"Coverage": "Azure Queue Services & Service Bus for Decoupling\nAzure Load Balancer & Application Gateway Basics\nApplication of Azure Functions & Azure App Services", "Daily Topic": "Core Azure Services: Compute, Messaging, Load Balancing & Databricks", "Focus of the week": "Week 2: Application Essentials & Generative AI Essentials"}'),
	(504, 21, 17, NULL, 'Middleware, Queues & Distributed Architecture - 1', '{"Coverage": "Middleware Patterns: Logging, Metrics, Retry, Circuit Breaker\nIntegrating Message Queues in Python (Azure Service Bus, RabbitMQ basics)\nLoad Balancing Strategies: Round Robin, Least Connections", "Daily Topic": "Middleware, Queues & Distributed Architecture - 1", "Focus of the week": "Week 2: Application Essentials & Generative AI Essentials"}'),
	(505, 21, 18, NULL, 'Middleware, Queues & Distributed Architecture - 2', '{"Coverage": "Using FastAPI/Flask with Uvicorn/Gunicorn for concurrency\nHealth Checks & Readiness Probes for Scalable APIs\nObservability: Structured Logging, Metrics (prometheus_client)", "Daily Topic": "Middleware, Queues & Distributed Architecture - 2", "Focus of the week": "Week 2: Application Essentials & Generative AI Essentials"}'),
	(506, 21, 19, NULL, 'Introduction to Generative AI', '{"Coverage": "What is Generative AI?\nTypes: Text, Image, Audio, Code generation\nKey models: GPT, DALL·E, Codex, Stable Diffusion (Diffusion, GANs, Transformers)\nApplications in enterprise AI (Use cases across industries)", "Daily Topic": "Introduction to Generative AI", "Focus of the week": "Week 2: Application Essentials & Generative AI Essentials"}'),
	(507, 21, 20, NULL, 'LLM Fundamentals', '{"Coverage": "Anatomy of LLMs (GPT, BERT, LLaMA)\nTransformer architecture basics\nPretraining vs. fine-tuning\nTokenization, embeddings\nClaude model family (Claude 3 – Opus, Sonnet, Haiku);\nComparison with GPT & open-source models; long context window capabilities", "Daily Topic": "LLM Fundamentals", "Focus of the week": "Week 2: Application Essentials & Generative AI Essentials"}'),
	(508, 21, 21, NULL, 'Prompt Engineering & Model APIs', '{"Coverage": "Prompt types: zero-shot, few-shot, chain-of-thought\nPrompt tuning\nPrompt design principles\nPrompt evaluation & debugging\nTools: LangChain, PromptLayer\nUsing OpenAI, Azure OpenAI, Anthropic APIs\nClaude-specific prompting techniques (structured prompts,\nConstitutional AI style prompting); differences vs GPT prompting; Claude API usage via direct API & LangChain", "Daily Topic": "Prompt Engineering & Model APIs", "Focus of the week": "Week 2: Application Essentials & Generative AI Essentials"}'),
	(509, 21, 23, NULL, 'Retrieval-Augmented Generation (RAG) & Vector Databases', '{"Coverage": "RAG architecture and flow\nVector DBs: Pinecone, Weaviate, FAISS, Azure AI Search\nIndexing, retrieval, and latency considerations\nUsing Claude in RAG pipelines; leveraging large context window vs retrieval; hybrid RAG + long-context approach", "Daily Topic": "Retrieval-Augmented Generation (RAG) & Vector Databases", "Focus of the week": "Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}'),
	(510, 21, 24, NULL, 'Gen AI Experimentation', '{"Coverage": "Experimentation - Metrics Evaluation, Understanding Benchmarks, Understanding Model Capabilities\nTracking model performance\nLogging outcome and feedback loops.", "Daily Topic": "Gen AI Experimentation", "Focus of the week": "Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}'),
	(511, 21, 25, NULL, 'Gen AI Governance, Guardrails & Deployment Frameworks', '{"Coverage": "Responsible AI principles (bias, hallucination, explainability)\nGuardrails: moderation, safety layers\nResponsible AI practices: EY principles\nFrameworks: LangChain, LlamaIndex, Haystack\nDeployment considerations: cost, latency, compliance", "Daily Topic": "Gen AI Governance, Guardrails & Deployment Frameworks", "Focus of the week": "Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}'),
