	(512, 21, 26, NULL, 'Putting It All Together: Gen AI Use Case & Deployment', '{"Coverage": "Gen AI API Example: Calling Azure OpenAI / HuggingFace APIs (simple RAG without vector DB)\nWrap-up: Best Practices, CI/CD Overview, Q&A & Next Steps\nClaude API integration alongside Azure OpenAI & HuggingFace; multi-model routing strategies", "Daily Topic": "Putting It All Together: Gen AI Use Case & Deployment", "Focus of the week": "Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}'),
	(513, 21, 28, NULL, 'Foundations of Agentic AI', '{"Coverage": "What is Agentic AI? How it differs from traditional AI and GenAI?\nCore capabilities: Perceive, Reason, Act, Learn\nSingle-agent vs. Multi-agent systems\nReal-world applications: healthcare, mobility, customer service\nUsing Claude for reasoning-heavy tasks; multi-step decision-making capabilities in agents", "Daily Topic": "Foundations of Agentic AI", "Focus of the week": "Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}'),
	(514, 21, 29, NULL, 'Lifecycle & Frameworks', '{"Coverage": "Agent lifecycle and planning loops\nFrameworks: LangChain, LangGraph\nIntegration of Claude with LangChain and LangGraph for agent workflows", "Daily Topic": "Lifecycle & Frameworks", "Focus of the week": "Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}'),
