	(526, 21, 44, NULL, 'Creating a Storyboard', '{"Coverage": "Definition and purpose of storyboard\nExamples of storyboards and how storyboards enhance clarity and engagement\nElements of a good storyboard: Structure, Visual hierarchy and flow; Matching visuals to key messages\nStoryboarding tools: Canva\nAligning storyboard with audience needs", "Daily Topic": "Creating a Storyboard", "Focus of the week": "Week 6: Effective Presentations"}'),
